package com.kitchenos.connect.kitchen;
import android.content.Context;
import android.content.SharedPreferences;
import android.net.Uri;
import com.kitchenos.common.Pairing;
import com.kitchenos.connect.ui.RecipePresentation;
import java.io.IOException;
import java.math.*;
import java.time.*;
import java.util.*;
import org.json.*;

/** Append-only writer for Calomatik's existing planMeal sync contract.
 * A persisted operation is retried verbatim; no existing meal or profile is overwritten. */
public final class KalomatikPlanWriter {
    public interface Transport {JSONObject call(JSONObject request)throws Exception;}
    private static final Object LOCK=new Object();
    private final Context context;private final String owner;private final Transport transport;private final SharedPreferences pending,links;
    public KalomatikPlanWriter(Context context)throws Exception{this(context,new CloudSession(context)::calomatikSync);}
    public KalomatikPlanWriter(Context context,Transport transport)throws Exception{this.context=context.getApplicationContext();this.transport=transport;owner=new CloudSession(context).account().optString("uid");if(owner.isEmpty())throw new IOException("Bitte mit deinem Kalomatik-Konto anmelden.");String hash=Pairing.fingerprint(owner.getBytes(java.nio.charset.StandardCharsets.UTF_8));pending=context.getSharedPreferences("kalomatik-plan-outbox-"+hash,0);links=context.getSharedPreferences("kalomatik-plan-links-"+hash,0);}
    private void checkOwner()throws IOException{if(!owner.equals(new CloudSession(context).account().optString("uid")))throw new IOException("Dein Konto hat sich geändert. Öffne den Kochplan erneut.");}
    public JSONObject add(JSONObject card,String date,int cookingServings)throws Exception{
        checkOwner();LocalDate day=LocalDate.parse(date);if(!day.toString().equals(date)||cookingServings<1||cookingServings>20)throw new IOException("Bitte Datum und Portionen prüfen.");String sourceId=card.optString("id"),digest=card.optString("programDigest");String key=Pairing.fingerprint((sourceId+":"+digest+":"+date+":"+cookingServings).getBytes(java.nio.charset.StandardCharsets.UTF_8));JSONObject operation;
        synchronized(LOCK){checkOwner();String saved=pending.getString(key,"");if(saved.isEmpty()){operation=operation(card,date,cookingServings,UUID.randomUUID().toString(),UUID.randomUUID().toString());if(!pending.edit().putString(key,operation.toString()).commit())throw new IOException("Die Übertragung konnte nicht sicher vorgemerkt werden.");}else operation=new JSONObject(saved);}
        JSONObject response=transport.call(new JSONObject().put("action","push").put("operation",new JSONObject(operation.toString())));checkOwner();JSONArray entities=response.optJSONArray("entities");JSONObject expected=operation.getJSONArray("changes").getJSONObject(0).getJSONObject("entity");if(!"acknowledged".equals(response.optString("status"))||!operation.getString("operationId").equals(response.optString("operationId"))||entities==null||entities.length()!=1||!expected.getString("id").equals(entities.getJSONObject(0).optString("id"))||!"planMeal".equals(entities.getJSONObject(0).optString("type"))||response.optLong("revision")<1)throw new IOException("Der gemeinsame Kochplan hat die Übertragung noch nicht bestätigt. Versuche es erneut.");
        JSONObject acknowledged=entities.getJSONObject(0);if(acknowledged.optLong("revision")!=response.getLong("revision")||acknowledged.optInt("schemaVersion")!=1||acknowledged.optBoolean("deleted",true)||!same(expected.getJSONObject("data"),acknowledged.optJSONObject("data"))||!same(expected.getJSONObject("source"),acknowledged.optJSONObject("source")))throw new IOException("Der bestätigte Planeintrag passt nicht zu diesem Rezept.");
        JSONObject program=card.optJSONObject("machineProgram");if(program!=null&&program.optInt("servings")==cookingServings){JSONObject link=new JSONObject().put("revision",response.getLong("revision")).put("card",new JSONObject(card.toString()));if(!links.edit().putString(expected.getString("id"),link.toString()).commit())throw new IOException("Der Plan ist übertragen. Die lokale Maschinenanleitung konnte noch nicht verknüpft werden; versuche es erneut.");}
        if(!pending.edit().remove(key).commit())throw new IOException("Der Plan ist übertragen. Die lokale Bestätigung konnte noch nicht gespeichert werden; versuche es erneut.");return new JSONObject().put("id",expected.getString("id")).put("revision",response.getLong("revision")).put("date",date);
    }
    public JSONObject preparedCard(JSONObject planned)throws Exception{checkOwner();String saved=links.getString(planned.optString("id"),"");if(saved.isEmpty())return null;JSONObject link=new JSONObject(saved);if(link.optLong("revision")!=planned.optLong("revision"))return null;JSONObject card=link.getJSONObject("card"),program=card.optJSONObject("machineProgram");if(program==null||program.optInt("servings")!=planned.optInt("cookingPortions"))return null;MachineProgram.validate(program);return new JSONObject(card.toString());}
    public static JSONObject operation(JSONObject card,String date,int cookingServings,String operationId,String localId)throws Exception{
        if(!UUID.fromString(operationId).toString().equals(operationId)||!UUID.fromString(localId).toString().equals(localId)||!LocalDate.parse(date).toString().equals(date))throw new IOException("Ungültige Planungskennung.");JSONObject program=card.optJSONObject("machineProgram");int base=program==null?card.optInt("portion",card.optInt("servings",1)):program.getInt("servings");if(base<1||base>20||cookingServings<1||cookingServings>20)throw new IOException("Die ursprüngliche Portionsbasis fehlt.");JSONArray original=program==null?card.optJSONArray("ingredients"):MachineProgram.ingredients(program);if(original==null||original.length()==0||original.length()>80)throw new IOException("Die Zutatenliste fehlt.");JSONArray ingredients=new JSONArray();Map<String,String> ids=new LinkedHashMap<>();Map<String,Double> totals=new HashMap<>();
        for(int i=0;i<original.length();i++){JSONObject item=original.getJSONObject(i),copy=new JSONObject();String name=item.optString("name"),unit=item.optString("unit"),id=program==null?item.optString("id","ingredient-"+i):"ingredient-"+i;if(name.isEmpty()||name.length()>160||id.length()>100||ids.containsKey(name+"\n"+unit))throw new IOException("Die Zutatenliste ist nicht eindeutig.");Object amount=item.opt("amount");if(amount!=null&&amount!=JSONObject.NULL&&(!(amount instanceof Number)||!Double.isFinite(((Number)amount).doubleValue())||((Number)amount).doubleValue()<=0))throw new IOException("Eine Zutatenmenge ist unvollständig.");copy.put("id",id).put("name",name).put("amount",amount==null?JSONObject.NULL:amount).put("unit",unit);ingredients.put(copy);ids.put(name+"\n"+unit,id);if(amount instanceof Number)totals.put(name+"\n"+unit,((Number)amount).doubleValue());}
        JSONObject data=new JSONObject().put("id",localId).put("date",date).put("gericht",card.getString("title")).put("portion",base).put("cookingPortions",cookingServings).put("ingredients",ingredients).put("createdAt",Instant.now().toString());
        JSONObject guide=program==null?card.optJSONObject("guide"):machineGuide(program,ids,totals);if(guide!=null){guide=new JSONObject(guide.toString());if(completeGuide(guide,ingredients))guide.put("version",1).put("basisKey",basis(ingredients,base));else{guide.remove("version");guide.remove("basisKey");}data.put("recipeGuide",guide);}
        JSONObject nutrition=card.optJSONObject("knownNutrition");if(nutrition!=null){String[][] fields={{"calories","kalorien"},{"protein","protein"},{"fat","fett"},{"carbs","kohlenhydrate"},{"fiber","ballaststoffe"}};for(String[] field:fields){Object raw=nutrition.opt(field[0]);if(raw instanceof Number&&Double.isFinite(((Number)raw).doubleValue())&&((Number)raw).doubleValue()>=0)data.put(field[1],((Number)raw).doubleValue()*base);}}
        String record="meal-plan:"+date;String id="v4:"+Uri.encode(new JSONArray().put("settings").put(record).put("meals").put(localId).toString());JSONObject entity=new JSONObject().put("type","planMeal").put("id",id).put("schemaVersion",1).put("deleted",false).put("data",data).put("source",new JSONObject().put("store","settings").put("key",record).put("path",new JSONArray().put("meals").put(localId)));
        JSONObject operation=new JSONObject().put("schemaVersion",1).put("kind","entities.batch").put("operationId",operationId).put("occurredAt",Instant.now().toString()).put("changes",new JSONArray().put(new JSONObject().put("baseRevision",0).put("localVersion",1).put("entity",entity)));if(operation.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>480000)throw new IOException("Dieses Rezept ist zu groß für die Übertragung.");return operation;
    }
    private static JSONObject machineGuide(JSONObject program,Map<String,String> ids,Map<String,Double> totals)throws Exception{MachineProgram.validate(program);JSONArray steps=new JSONArray(),source=program.getJSONArray("steps"),equipment=new JSONArray(),tools=program.optJSONArray("tools");for(int i=0;tools!=null&&i<tools.length();i++)equipment.put(MachineProgram.toolName(tools.getString(i)));for(int i=0;i<source.length();i++){JSONObject step=source.getJSONObject(i);if(RecipePresentation.omitted(step))continue;JSONArray refs=new JSONArray(),uses=step.getJSONArray("ingredients");for(int j=0;j<uses.length();j++){JSONObject use=uses.getJSONObject(j);String key=use.getString("name")+"\n"+use.getString("unit");Double total=totals.get(key);if(total==null||ids.get(key)==null)continue;double share=use.getDouble("amount")/total;JSONObject existing=null;for(int r=0;r<refs.length();r++)if(ids.get(key).equals(refs.getJSONObject(r).optString("ingredientId")))existing=refs.getJSONObject(r);if(existing==null)refs.put(new JSONObject().put("ingredientId",ids.get(key)).put("share",share));else existing.put("share",existing.getDouble("share")+share);}JSONObject settings=step.getJSONObject("settings");String instruction=step.getString("instruction");if(step.optString("kind").equals("machine"))instruction+="\nMaschine: "+settings.getInt("durationSeconds")+" Sekunden, "+(settings.getDouble("temperatureC")==0?"Heizung aus":settings.getDouble("temperatureC")+" °C")+", Stufe "+settings.getDouble("speedLevel")+", "+(settings.getDouble("speedLevel")==0?"Messer steht":("counterclockwise".equals(settings.optString("direction"))?"Rühren":"Messer"))+".";JSONObject row=new JSONObject().put("title",step.getString("title")).put("instruction",instruction).put("ingredients",refs).put("minutes",settings.isNull("durationSeconds")?JSONObject.NULL:settings.getInt("durationSeconds")/60d).put("temperatureC",settings.opt("temperatureC")).put("heat",step.optString("kind").equals("machine")?"Küchenmaschine":JSONObject.NULL).put("cue",step.getString("instruction").substring(0,Math.min(1000,step.getString("instruction").length()))).put("imagePrompt",step.getString("instruction").substring(0,Math.min(1200,step.getString("instruction").length())));steps.put(row);}return new JSONObject().put("title",program.getString("title")).put("prepMinutes",JSONObject.NULL).put("cookMinutes",JSONObject.NULL).put("restMinutes",JSONObject.NULL).put("equipment",equipment).put("tips",new JSONArray()).put("steps",steps);}
    /** Mirrors the shared recipe skill before declaring a guide current; incomplete source guides stay unbound. */
    private static boolean completeGuide(JSONObject guide,JSONArray ingredients){try{
        if(!validText(guide.opt("title"),180)||!Arrays.asList("einfach","mittel","anspruchsvoll").contains(guide.optString("difficulty")))return false;
        JSONArray equipment=guide.getJSONArray("equipment"),tips=guide.getJSONArray("tips"),steps=guide.getJSONArray("steps");
        if(equipment.length()>20||tips.length()>10||steps.length()<1||steps.length()>30)return false;
        for(int i=0;i<equipment.length();i++)if(!validText(equipment.get(i),160))return false;for(int i=0;i<tips.length();i++)if(!validText(tips.get(i),1000))return false;
        for(String field:new String[]{"prepMinutes","cookMinutes","restMinutes"})if(!nullableNumber(guide,field,4320))return false;
        Set<String> ids=new HashSet<>();Map<String,Double> used=new HashMap<>();for(int i=0;i<ingredients.length();i++)ids.add(ingredients.getJSONObject(i).getString("id"));
        for(int i=0;i<steps.length();i++){JSONObject step=steps.getJSONObject(i);if(!validText(step.opt("title"),160)||!validText(step.opt("instruction"),2000)||!validText(step.opt("cue"),1000)||!nullableNumber(step,"minutes",4320)||!nullableNumber(step,"temperatureC",500)||!nullableText(step,"heat",160)||!nullableText(step,"imagePrompt",1200))return false;JSONArray refs=step.getJSONArray("ingredients");if(refs.length()>30)return false;Set<String> seen=new HashSet<>();for(int j=0;j<refs.length();j++){JSONObject ref=refs.getJSONObject(j);String id=ref.getString("ingredientId");Object raw=ref.get("share");if(!(raw instanceof Number))return false;double share=((Number)raw).doubleValue();if(!ids.contains(id)||!seen.add(id)||!Double.isFinite(share)||share<=0||share>1)return false;used.put(id,used.getOrDefault(id,0d)+share);}}
        for(String id:ids)if(Math.abs(used.getOrDefault(id,0d)-1)>.000001)return false;return true;
    }catch(Exception invalid){return false;}}
    private static boolean validText(Object raw,int max){return raw instanceof String&&!((String)raw).trim().isEmpty()&&((String)raw).length()<=max;}
    private static boolean nullableText(JSONObject value,String field,int max){return value.has(field)&&(value.isNull(field)||validText(value.opt(field),max));}
    private static boolean nullableNumber(JSONObject value,String field,double max){Object raw=value.opt(field);return value.has(field)&&(raw==JSONObject.NULL||(raw instanceof Number&&Double.isFinite(((Number)raw).doubleValue())&&((Number)raw).doubleValue()>=0&&((Number)raw).doubleValue()<=max));}
    private static String basis(JSONArray ingredients,int servings)throws Exception{StringBuilder text=new StringBuilder("[");for(int i=0;i<ingredients.length();i++){JSONObject item=ingredients.getJSONObject(i);if(i>0)text.append(',');String amount=item.isNull("amount")?"null":new BigDecimal(item.getDouble("amount")/servings).setScale(6,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();text.append("{\"id\":").append(JSONObject.quote(item.getString("id"))).append(",\"name\":").append(JSONObject.quote(item.getString("name"))).append(",\"amount\":").append(amount).append(",\"unit\":").append(JSONObject.quote(item.optString("unit").isEmpty()?"g":item.getString("unit"))).append('}');}return text.append(']').toString();}
    private static boolean same(Object a,Object b)throws Exception{if(a==null||a==JSONObject.NULL)return b==null||b==JSONObject.NULL;if(a instanceof Number&&b instanceof Number)return new BigDecimal(a.toString()).compareTo(new BigDecimal(b.toString()))==0;if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> keys=x.keys();while(keys.hasNext()){String key=keys.next();if(!y.has(key)||!same(x.get(key),y.get(key)))return false;}return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!same(x.get(i),y.get(i)))return false;return true;}return a.equals(b);}
}
